import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Analysis features","description":"Cross-run drift, cost anomaly detection, IaC gap detection, and IoT deep coverage.","frontmatter":{"description":"Cross-run drift, cost anomaly detection, IaC gap detection, and IoT deep coverage."},"headers":[],"relativePath":"assessment/analysis-features.md","filePath":"assessment/analysis-features.md"}'),n={name:"assessment/analysis-features.md"};function o(r,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="analysis-features" tabindex="-1">Analysis features <a class="header-anchor" href="#analysis-features" aria-label="Permalink to &quot;Analysis features&quot;">​</a></h1><p>Beyond scoring a single run, AzureScout compares runs over time and applies a few targeted analyses to the collected data. All of these run from data already collected — none of them makes an extra Azure call.</p><p>These were previously buried in the middle of the assessment platform page, between the scoring model and the report tiers, where nobody looking for them would find them.</p><h2 id="cross-run-drift" tabindex="-1">Cross-run drift <a class="header-anchor" href="#cross-run-drift" aria-label="Permalink to &quot;Cross-run drift&quot;">​</a></h2><p><code>Get-ScoutDrift</code> computes drift between the current run and the previous run for the same assessment: each finding is classified <strong>New</strong>, <strong>Resolved</strong> (<code>Fail</code>/<code>Partial</code> → <code>Pass</code>), <strong>Regressed</strong> (<code>Pass</code> → <code>Fail</code>/<code>Partial</code>), or <strong>Unchanged</strong>, plus an overall weighted score delta. History is kept in an append-only <code>findings-history.json</code> under a <code>.scout-history/</code> folder in the output root, keyed by run id — the first run for a given assessment becomes the baseline (nothing to diff against yet). Assessment mode computes drift automatically after scoring and feeds it into the <a href="#report-tiers">React report</a>&#39;s Drift tab; a drift computation failure is non-fatal to the rest of the run.</p><h2 id="cross-run-resource-inventory-drift" tabindex="-1">Cross-run resource (inventory) drift <a class="header-anchor" href="#cross-run-resource-inventory-drift" aria-label="Permalink to &quot;Cross-run resource (inventory) drift&quot;">​</a></h2><p><code>Get-ScoutInventoryDrift</code> (AB#326) is the resource-level counterpart to <code>Get-ScoutDrift</code> above: <code>Get-ScoutDrift</code> tracks how each <strong>rule</strong> scored across runs, while <code>Get-ScoutInventoryDrift</code> tracks what actually changed in the <strong>collected Azure estate itself</strong> — independent of how any rule scored it. It is not wired into assessment mode automatically; call it yourself with the same <code>collect.json</code> and a caller-controlled run id:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$collect </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Get-Content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20260724_101500</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">collect.json </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Raw </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ConvertFrom-Json</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ScoutInventoryDrift</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Collect $collect </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HistoryPath .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">output</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.scout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RunId </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;20260724_101500&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Each resource gets a stable id built from whichever recognized identity fields it carries (falling back to a content hash so nothing is silently dropped), then compared against the previous run&#39;s snapshot: <strong>Added</strong>, <strong>Removed</strong>, <strong>Changed</strong> (with a per-field before/after diff), or <strong>Unchanged</strong> (rolled into the summary count only). The first-ever run for a given <code>-HistoryPath</code> returns an explicit baseline (<code>IsBaseline = $true</code>) rather than reporting every resource as Added. History is appended to <code>inventory-history.json</code>, alongside <code>Get-ScoutDrift</code>&#39;s <code>findings-history.json</code>, under the same <code>.scout-history/</code> folder.</p><h2 id="cost-anomaly-detection" tabindex="-1">Cost anomaly detection <a class="header-anchor" href="#cost-anomaly-detection" aria-label="Permalink to &quot;Cost anomaly detection&quot;">​</a></h2><p><code>Get-ScoutCostAnomaly</code> (AB#324) is an offline analysis function — it never calls Azure. Point it at an already-collected cost dataset (the raw <code>Get-AZSCCostInventory</code> shape, or a pre-normalized array of cost records) and it flags outliers using three independent techniques: a sudden month-over-month spike, a z-score check, and an IQR (Tukey) check, grouped by <code>-GroupBy</code> (default <code>Scope</code>, <code>ResourceType</code>). It also always returns the top movers by absolute dollar swing, independent of whether anything crossed a threshold.</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ScoutCostAnomaly</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CostData $costData </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ZScoreThreshold </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SpikeThresholdPct </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">75</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">Needs more than the default 2-month lookback for z-score/IQR</p><p>The z-score and IQR techniques need at least <code>-MinDataPoints</code> (default 4) periods per group; the default <code>Get-AZSCCostInventory</code> lookback is only 2 months, so only spike detection reliably fires unless you collect cost data with a longer <code>-Days</code> window first.</p></div><h2 id="iac-gap-detection" tabindex="-1">IaC gap detection <a class="header-anchor" href="#iac-gap-detection" aria-label="Permalink to &quot;IaC gap detection&quot;">​</a></h2><p><code>Get-ScoutIacGap</code> (AB#325) is an offline analysis function — it never calls Azure. It compares resources discovered in <code>collect.json</code> against a folder of <code>.bicep</code>/ARM-JSON templates (best-effort text/JSON parsing — no <code>bicep build</code> or other external dependency) and reports resources that exist in Azure but aren&#39;t represented in any template (<code>Unmanaged</code>).</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ScoutIacGap</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CollectData $collect </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TemplatePath .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">infra </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IncludeTemplatedButMissing</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Matching is exact on a normalized (Type, Name) pair — it does not currently account for a resource being deployed to a different resource group/ subscription than its template declares.</p><h2 id="iot-deep-coverage" tabindex="-1">IoT deep coverage <a class="header-anchor" href="#iot-deep-coverage" aria-label="Permalink to &quot;IoT deep coverage&quot;">​</a></h2><p>The Collect layer&#39;s IoT queries (<code>Invoke-Collect</code>, AB#330) now go beyond IoT Hub device registries to include <strong>Device Provisioning Service</strong> (DPS) and <strong>Azure Digital Twins</strong> instances, scored by the <code>caf.iot</code> rule file — so <code>-Assessment &#39;Assess: IoT&#39;</code> (and <code>LandingZone</code>) picks up DPS/Digital Twins findings without any extra configuration.</p>`,19)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
